UIShieldSparkEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,50);this.particleClass=UISparkParticle;this.makeParticles('game',['shieldSpark']);this.particleDrag.setTo(100,100);this.setAlpha(0.8,1.0);this.setRotation(0,0);this.minParticleScale=UIConstants.GAME_ASSET_SCALE*0.8;this.maxParticleScale=UIConstants.GAME_ASSET_SCALE;this.gravity=0;this.kill();this.visible=false;};UIShieldSparkEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UIShieldSparkEmitter.prototype.constructor=UIShieldSparkEmitter;UIShieldSparkEmitter.prototype.preUpdate=function(){if(!this.exists||this.game.physics.arcade.isPaused){return false;}return Phaser.Particles.Arcade.Emitter.prototype.preUpdate.call(this);};UIShieldSparkEmitter.prototype.update=function(){if(!this.exists||this.game.physics.arcade.isPaused){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);if(this.countLiving()==0){this.kill();this.visible=false;}};UIShieldSparkEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UIShieldSparkEmitter.prototype.emit=function(x,y,rotation){this.revive();this.visible=true;var speedX=Math.cos(rotation)*UIConstants.SHIELD_SPARK_SPEED;var speedY=Math.sin(rotation)*UIConstants.SHIELD_SPARK_SPEED;this.minParticleSpeed.setTo(speedX-UIConstants.SHIELD_SPARK_RANDOM_SPEED,speedY-UIConstants.SHIELD_SPARK_RANDOM_SPEED);this.maxParticleSpeed.setTo(speedX+UIConstants.SHIELD_SPARK_RANDOM_SPEED,speedY+UIConstants.SHIELD_SPARK_RANDOM_SPEED);this.emitX=x;this.emitY=y;this.explode(1000,QualityManager.getQualityValue(QualityManager.QUALITY_PARAMETERS.SHIELD_SPARK_PARTICLES_PER_EMIT));};UIShieldSparkEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};